mat2 rot(float a) { float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }

vec3 getPalette(float t, int mode) {
    vec3 a, b, c, d;
    if (mode == 0) { a = vec3(0.5, 0.5, 0.5); b = vec3(0.5, 0.5, 0.5); c = vec3(1.0, 0.7, 0.4); d = vec3(0.0, 0.15, 0.2); }
    else if (mode == 1) { a = vec3(0.5, 0.5, 0.5); b = vec3(0.5, 0.5, 0.5); c = vec3(1.0, 1.0, 0.0); d = vec3(0.8, 0.9, 0.3); }
    else if (mode == 2) { a = vec3(0.5, 0.5, 0.5); b = vec3(0.5, 0.5, 0.5); c = vec3(1.0, 0.0, 0.0); d = vec3(0.0, 0.33, 0.67); }
    else if (mode == 3) { a = vec3(0.5, 0.5, 0.8); b = vec3(0.5, 0.5, 0.5); c = vec3(0.0, 1.0, 1.0); d = vec3(0.0, 0.1, 0.2); }
    else if (mode == 4) { a = vec3(0.1, 0.1, 0.2); b = vec3(0.3, 0.2, 0.4); c = vec3(0.8, 0.4, 1.0); d = vec3(0.0, 0.5, 0.5); }
    else { a = vec3(0.5, 0.5, 0.5); b = vec3(0.5, 0.5, 0.5); c = vec3(1.0, 1.0, 1.0); d = vec3(0.0, 0.33, 0.67); }
    return a + b * cos(6.28318 * (c * t + d));
}

void kaleido(inout vec2 p, int n) {
    float angle = 3.14159 / float(n);
    for (int i = 0; i < 12; i++) {
        if (i >= n) break;
        p = abs(p);
        p *= rot(angle);
    }
}

float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float fractal(vec3 p, float morph) {
    float scale = 2.0 + morph * 0.5;
    float d = sdBox(p, vec3(1.0));
    float s = 1.0;
    for (int i = 0; i < 5; i++) {
        vec3 a = mod(p * s, 2.0) - 1.0;
        s *= scale;
        vec3 r = abs(1.0 - 3.0 * abs(a));
        float da = max(r.x, r.y);
        float db = max(r.y, r.z);
        float dc = max(r.z, r.x);
        float c = (min(da, min(db, dc)) - 1.0) / s;
        d = max(d, c);
    }
    return d;
}

float hyperTunnel(vec3 p, float twist, float morph) {
    float angle = atan(p.y, p.x);
    float r = length(p.xy);
    p.xy = vec2(r - 2.0, angle * 0.5 + p.z * twist);
    vec2 cell = floor(p.xz);
    p.xz = fract(p.xz) - 0.5;
    float d1 = length(p) - 0.3 - morph * 0.1;
    float d2 = sdBox(p, vec3(0.2 + morph * 0.1));
    return mix(d1, d2, morph);
}

float scene(vec3 p, float t, float dim, float warpAmt, float morphVal) {
    p.xy *= rot(t * 0.1);
    p.xz *= rot(t * 0.07);
    float warpPhase = sin(t * 0.3) * warpAmt;
    p += sin(p.zxy * 0.5 + t) * warpPhase;
    float d1 = fractal(p * 0.5, morphVal) * 2.0;
    float d2 = hyperTunnel(p, 0.2 + sin(t * 0.1) * 0.1, morphVal);
    return mix(d1, d2, dim);
}

vec3 shader(vec2 uv, float time) {
    float t = time * speed;
    float beatPulse = pow(1.0 - beat, 4.0) * beatReact;
    float morphVal = complexity + (pulseMode == 0 || pulseMode == 3 ? beatPulse * 0.3 : 0.0);
    float zoomMod = 1.0 + (pulseMode == 2 || pulseMode == 3 ? beatPulse * 0.2 : 0.0);
    float colorShift = (pulseMode == 1 || pulseMode == 3 ? beatPulse : 0.0);
    uv = uv * 2.0 - 1.0;
    uv.x *= resolution.x / resolution.y;
    kaleido(uv, folds);
    uv *= rot(t * rotation);
    vec3 ro = vec3(0.0, 0.0, t * 3.0);
    vec3 rd = normalize(vec3(uv * zoomMod, 1.5));
    rd.xy *= rot(sin(t * 0.2) * 0.3);
    rd.xz *= rot(cos(t * 0.15) * 0.2);
    float totalDist = 0.0;
    float minDist = 1000.0;
    vec3 col = vec3(0.0);
    float glowAccum = 0.0;
    for (int i = 0; i < 80; i++) {
        vec3 p = ro + rd * totalDist;
        float d = scene(p, t, dimension, warp, morphVal);
        minDist = min(minDist, d);
        glowAccum += 0.02 / (0.1 + abs(d));
        if (d < 0.001 || totalDist > 50.0) break;
        totalDist += d * 0.7;
    }
    float depth = totalDist / 50.0;
    float edge = 1.0 - smoothstep(0.0, 0.1, minDist);
    float colorIndex = depth * 3.0 + t * 0.5 + edge * 2.0 + colorShift;
    col = getPalette(colorIndex, palette);
    col *= 1.0 - depth * 0.8;
    col += glowAccum * glow * 0.03 * getPalette(colorIndex + 0.2, palette);
    col += edge * 0.5 * getPalette(colorIndex + 0.5, palette);
    float vignette = 1.0 - length(uv) * 0.3;
    col *= vignette;
    col = mix(vec3(dot(col, vec3(0.299, 0.587, 0.114))), col, saturation);
    col = pow(col, vec3(0.85));
    col = clamp(col, 0.0, 1.0);
    return col;
}
